"""Add the AprilTag panels using the SDF models generated by curtmini_piper_gz_sim."""

from curtmini_piper_gz_sim.apriltags import apriltag_model_sdf, load_apriltags

from .robot_mjcf import rpy_to_quat
from .world_mjcf import add_sdf_model


def add_apriltags(spec, settings, layout_file, model_dirs):
    skipped = []
    for tag in load_apriltags(layout_file):
        texture = f"model://apriltags/tag36_11_{tag['id']:05d}.png"
        pose = tag['pose']
        skipped += add_sdf_model(
            spec, settings, apriltag_model_sdf(tag, texture),
            [pose['x'], pose['y'], pose['z']],
            rpy_to_quat([pose['roll'], pose['pitch'], pose['yaw']]), model_dirs)
    return skipped
